dtsPropsFor.Icon:
/** Clé de l'inventaire ICONS (ex. 'home', 'cards', 'target', 'filePdf'). */
  name: string;
  /** Côté du carré SVG, en px. */
  size?: number;
  /** Épaisseur du tracé. */
  stroke?: number;
  className?: string;
  style?: React.CSSProperties;
  /** Remplit la forme au lieu de la tracer. */
  fill?: boolean;

dtsPropsFor.Card:
/** Sans titre, l'en-tête entier (titre, icône, action) est omis. */
  title?: React.ReactNode;
  /** Nom d'icône affiché devant le titre. */
  icon?: string;
  /** Contenu aligné à droite de l'en-tête (bouton, pastille…). */
  action?: React.ReactNode;
  children?: React.ReactNode;
  style?: React.CSSProperties;
  className?: string;

dtsPropsFor.Switch:
on: boolean;
  /** Reçoit la valeur SUIVANTE, pas l'événement. */
  onChange: (next: boolean) => void;

dtsPropsFor.TypeChip:
type: 'qcm' | 'flashcard' | 'feynman';
  /** Préfixe le libellé quand il est fourni. */
  count?: number;

dtsPropsFor.SplitHandle:
/** De quel côté du contenu central vit le panneau commandé. */
  side: 'left' | 'right';
  collapsed: boolean;
  onClick: () => void;

dtsPropsFor.EdTop:
theme: 'light' | 'dark';
  onTheme: () => void;
  /** Omis ⇒ le bouton de retour au hub n'est pas rendu. */
  onHub?: () => void;

dtsPropsFor.BellButton:
/** true = rappels J actifs ; false = cours en pause. */
  on: boolean;
  onToggle: () => void;
  /** Textes de l'infobulle, si les libellés par défaut ne conviennent pas. */
  onText?: string;
  offText?: string;

dtsPropsFor.EtiquetteQuickSet:
value?: 'a_apprendre' | 'a_reapprendre' | 'revision_j' | null;
  /** null = retirer l'étiquette. */
  onChange: (value: 'a_apprendre' | 'a_reapprendre' | 'revision_j' | null) => void;

dtsPropsFor.Modal:
title?: React.ReactNode;
  onClose: () => void;
  /** Toute largeur CSS ; défaut 'min(560px, 94vw)'. */
  width?: string;
  children?: React.ReactNode;

dtsPropsFor.ConfirmModal:
title: React.ReactNode;
  body?: React.ReactNode;
  confirmLabel?: string;
  /** Colore le bouton de confirmation en rouge. */
  danger?: boolean;
  onConfirm: () => void;
  onCancel: () => void;

dtsPropsFor.DateActionModal:
title: React.ReactNode;
  body?: React.ReactNode;
  /** Libellé du champ de date. */
  label?: string;
  confirmLabel?: string;
  /** Nombre d'éléments concernés, affiché près du champ. */
  count?: number;
  /** Borne basse ISO (AAAA-MM-JJ). */
  minDate?: string;
  /** Autorise une date passée. */
  allowPast?: boolean;
  onConfirm: (dateISO: string) => void;
  onCancel: () => void;

dtsPropsFor.ContextMenu:
/** Position fixe, en coordonnées viewport. */
  x: number;
  y: number;
  items: Array<{ label: React.ReactNode; icon?: string; onClick: () => void; danger?: boolean }>;
  /** Appelé au clic ailleurs, au défilement et à Échap. */
  onClose: () => void;

dtsPropsFor.SessionTrendChart:
/** `rate` dans [0,1]. Moins de 2 points ⇒ rien n'est rendu. */
  points: Array<{ date: string; rate: number }>;
  height?: number;

dtsPropsFor.TodaySeriesCard:
/** Série du jour, dans l'ordre de révision. */
  plan: Array<{ fiche: { id: string; titre: string; type?: string }; matiere?: { nom: string; couleur?: string; icon?: string }; jLabel: string; qcm: number; flash: number; items: unknown[] }>;
  onStart: (items: unknown[], title: string) => void;
  /** Variante dense. */
  compact?: boolean;
  collapsed?: boolean;
  /** Omis ⇒ aucune poignée de repli. */
  onToggleCollapse?: () => void;

dtsPropsFor.OverdueBox:
/** Une entrée par fiche en retard. */
  groups: Array<{ fiche: { id: string; titre: string; type?: string }; matiere?: { nom: string; couleur?: string; icon?: string }; items: unknown[]; isSchema?: boolean }>;
  onStartFiche: (group: { fiche: { id: string; titre: string; type?: string }; items: unknown[]; isSchema?: boolean }) => void;
  onStartAll: (items: unknown[]) => void;
  /** Omis ⇒ pas de bouton « retirer du retard ». */
  onDismissFiche?: (group: { fiche: { id: string; titre: string; type?: string } }) => void;
  collapsible?: boolean;
  collapsed?: boolean;
  onToggleCollapse?: () => void;
  /** Rend le contenu nu, sans la carte englobante. */
  bare?: boolean;

dtsPropsFor.DossierRow:
dossier: { id: string; nom: string; parentId?: string | null; matiereId: string };
  isOpen: boolean;
  fichesCount: number;
  /** Renseigné sur une unité (ajoute « · N chapitres »), absent sur un chapitre. */
  sousDossiersCount?: number;
  exosCount?: number;
  /** Omis ⇒ pas de bouton « exercices du chapitre ». */
  onOpenExos?: () => void;
  isRenaming?: boolean;
  /** Champ de saisie inséré tel quel quand isRenaming. */
  renameInput?: React.ReactNode;
  onToggle: () => void;
  onRename: () => void;
  onMenu: (e: React.MouseEvent<HTMLButtonElement>) => void;

dtsPropsFor.DossierAddButton:
onClick: () => void;
  label?: string;
  style?: React.CSSProperties;

dtsPropsFor.CourseDocField:
/** PDF ou HTML ; null ⇒ zone de dépôt. */
  file?: File | null;
  /** null = retirer le document. */
  onFile: (file: File | null) => void;
  label?: string;
  hint?: React.ReactNode;

dtsPropsFor.FicheDndProvider:
/** Appelé au dépôt ; dossierId null = racine de la matière, beforeFicheId null = fin de liste. */
  onDropAt: (target: { ficheId: string; matiereId: string; dossierId: string | null; beforeFicheId: string | null }) => void;
  /** Rendu de la fiche pendant le glisser. */
  renderOverlay: (ficheId: string) => React.ReactNode;
  children?: React.ReactNode;

dtsPropsFor.DraggableFiche:
/** Doit être rendu dans un FicheDndProvider. */
  id: string;
  disabled?: boolean;
  className?: string;
  style?: React.CSSProperties;
  children?: React.ReactNode;

dtsPropsFor.DropSlot:
/** Doit être rendu dans un FicheDndProvider. */
  matiereId: string;
  /** null = racine de la matière. */
  dossierId?: string | null;
  /** null = fin de liste. */
  beforeId?: string | null;
  /** 'line' = barre d'insertion fine ; 'zone' = zone « déposer ici ». */
  variant?: 'line' | 'zone';
  label?: string;
